if (b.length == n) {
    return true;
}
if (n == 0) {
    deallocate(p, data, max_size, b);
    return true;
}
if (!b) {
    b = allocate(p, data, max_size, alignment, n);
    return true;
}
size_t alignedLength = round_to_alignment(alignment, n);
if (is_last_used_block(data, p, b)) {
    if (static_cast<char*>(b.ptr) + alignedLength <= data + max_size) {
        b.length = alignedLength;
        p = static_cast<char*>(b.ptr) + alignedLength;
        return true;
    }
    return false;
}
if (b.length > n) {
    b.length = round_to_alignment(alignment, n);
    return true;
}
block newBlock = allocate(p, data, max_size, alignment, alignedLength);
if (newBlock) {
    size_t copySize = std::min(b.length, alignedLength);
    std::memcpy(newBlock.ptr, b.ptr, copySize);
    b = newBlock;
    return true;
}
return false;

